      let ok = true, upstream = null;
      try { upstream = await api("GET", "/health"); ok = upstream.status === 200; } catch { ok = false; }
      return send(res, ok ? 200 : 503, { ok, ui: true, api: upstream ? upstream.data : null });
    }

    // Proxy every read and write to the api service.
    if (path === "/api/items") {
      if (method === "GET") {
        const r = await api("GET", "/items");
        return send(res, r.status, r.data);
      }
      if (method === "POST") {
        const body = await readBody(req);
        if (!body || typeof body.text !== "string" || !body.text.trim())
          return send(res, 400, { error: "text is required" });
        const r = await api("POST", "/items", { text: body.text.trim() });
        return send(res, r.status, r.data);
      }
      return send(res, 405, { error: "method not allowed" });
    }

    const m = path.match(/^\/api\/items\/(.+)$/);
    if (m) {
      const id = decodeURIComponent(m[1]);
      if (method === "PATCH") {
        const body = await readBody(req);
        if (!body || typeof body !== "object") return send(res, 400, { error: "bad json" });
        const patch = {};
        if ("bought" in body) patch.bought = !!body.bought;
        if ("text" in body) {
          if (typeof body.text !== "string" || !body.text.trim()) return send(res, 400, { error: "text is required" });
          patch.text = body.text.trim();
