        const r = await api("PATCH", "/items/" + encodeURIComponent(id), patch);
        return send(res, r.status, r.data);
      }
      if (method === "DELETE") {
        const r = await api("DELETE", "/items/" + encodeURIComponent(id));
        if (r.status === 204) return send(res, 204, "");
        return send(res, r.status, r.data);
      }
      return send(res, 405, { error: "method not allowed" });
    }

    return send(res, 404, { error: "not found" });
  } catch (e) {
    return send(res, 502, { error: "api unavailable: " + (e && e.message ? e.message : String(e)) });
